using System;using System.Diagnostics;using System.Runtime.InteropServices;
class Ra2HouseProbe{[DllImport("kernel32.dll")]static extern IntPtr OpenProcess(uint a,bool b,int p);[DllImport("kernel32.dll")]static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[]b,int n,out IntPtr r);static void Main(){var g=Process.GetProcessesByName("game")[0];IntPtr h=OpenProcess(0x410,false,g.Id);uint p=0;byte[]b=new byte[4];IntPtr n;ReadProcessMemory(h,new IntPtr(0x00A35DB4),b,4,out n);p=BitConverter.ToUInt32(b,0);Console.WriteLine("PLAYER=0x{0:X8}",p);foreach(uint o in new[]{0x1E8B9530u,0x1E8B7100u}){ReadProcessMemory(h,new IntPtr(o+0x1B4),b,4,out n);uint owner=BitConverter.ToUInt32(b,0);ReadProcessMemory(h,new IntPtr(owner+0x18C),b,4,out n);Console.WriteLine("OBJ=0x{0:X8} OWNER=0x{1:X8} OWNER+18C=0x{2:X8}",o,owner,BitConverter.ToUInt32(b,0));}}}
